pub struct ScrollRequestInternal {
    /// Start ID to read points from.
    pub offset: Option<PointIdType>,
    /// Page size. Default: 10
    #[validate(range(min = 1))]
    pub limit: Option<usize>,
    /// Look only for points which satisfies this conditions. If not provided - all points.
    #[validate(nested)]
    pub filter: Option<Filter>,
    [...]
}

From lib/segment/src/types.rs (Filter struct):
pub struct Filter {
    /// At least one of those conditions should match
    #[validate(nested)]
    #[serde(default, with = "MaybeOneOrMany", skip_serializing_if = "Option::is_none")]
    pub should: Option<Vec<Condition>>,
    [...]
}

Note: Filter.should field is Option<Vec<Condition>> with validate(nested) decorator and serde(default) - this means empty vec [] is valid default. No explicit validation rejecting empty should array observed in source grep results.
